import { useEffect, useMemo, useState } from 'react';
import {
  Animated,
  Pressable,
  Text,
  View,
  type StyleProp,
  type ViewProps,
  type ViewStyle,
} from 'react-native';
import { useTokens } from '../../foundation/theme-provider';
import { DateWheelPicker } from './date-wheel-picker';

export type DatePickerWeekStartsOn = 0 | 1;

export type DatePickerProps = Omit<ViewProps, 'style'> & {
  value?: Date | null;
  defaultValue?: Date | null;
  onValueChange?: (date: Date) => void;
  displayedMonth?: Date;
  defaultDisplayedMonth?: Date;
  onDisplayedMonthChange?: (month: Date) => void;
  minDate?: Date;
  maxDate?: Date;
  isDateDisabled?: (date: Date) => boolean;
  weekStartsOn?: DatePickerWeekStartsOn;
  showOutsideDays?: boolean;
  locale?: string;
  disabled?: boolean;
  /**
   * iOS-style header: renders the month/year as a tappable dropdown that
   * expands an inline month-year wheel in place of the day grid.
   */
  monthYearDropdown?: boolean;
  style?: StyleProp<ViewStyle>;
};

const SUNDAY_LABELS = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
const MONDAY_LABELS = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];
const MONTH_NAMES = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
];

function startOfDay(date: Date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function startOfMonth(date: Date) {
  return new Date(date.getFullYear(), date.getMonth(), 1);
}

function addDays(date: Date, amount: number) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + amount);
}

function addMonths(date: Date, amount: number) {
  return new Date(date.getFullYear(), date.getMonth() + amount, 1);
}

function sameDay(a: Date | null | undefined, b: Date | null | undefined) {
  return Boolean(
    a &&
      b &&
      a.getFullYear() === b.getFullYear() &&
      a.getMonth() === b.getMonth() &&
      a.getDate() === b.getDate(),
  );
}

function monthLabel(date: Date, locale?: string) {
  try {
    return new Intl.DateTimeFormat(locale, { month: 'long', year: 'numeric' }).format(date);
  } catch {
    return `${MONTH_NAMES[date.getMonth()]} ${date.getFullYear()}`;
  }
}

function accessibilityDateLabel(date: Date, locale?: string) {
  try {
    return new Intl.DateTimeFormat(locale, {
      weekday: 'long',
      month: 'long',
      day: 'numeric',
      year: 'numeric',
    }).format(date);
  } catch {
    return `${MONTH_NAMES[date.getMonth()]} ${date.getDate()}, ${date.getFullYear()}`;
  }
}

function calendarDays(month: Date, weekStartsOn: DatePickerWeekStartsOn) {
  const first = startOfMonth(month);
  const leading = (first.getDay() - weekStartsOn + 7) % 7;
  const gridStart = addDays(first, -leading);
  return Array.from({ length: 42 }, (_, index) => addDays(gridStart, index));
}

export function DatePicker({
  value,
  defaultValue = null,
  onValueChange,
  displayedMonth,
  defaultDisplayedMonth,
  onDisplayedMonthChange,
  minDate,
  maxDate,
  isDateDisabled,
  weekStartsOn = 0,
  showOutsideDays = true,
  locale,
  disabled = false,
  monthYearDropdown = false,
  style,
  ...rest
}: DatePickerProps) {
  const t = useTokens();
  const today = useMemo(() => startOfDay(new Date()), []);
  const [pickerOpen, setPickerOpen] = useState(false);
  const [chevron] = useState(() => new Animated.Value(0));
  const [internalValue, setInternalValue] = useState<Date | null>(defaultValue);
  const selected = value === undefined ? internalValue : value;
  const initialMonth = defaultDisplayedMonth ?? selected ?? today;
  const [internalMonth, setInternalMonth] = useState(() => startOfMonth(initialMonth));
  const month = startOfMonth(displayedMonth ?? internalMonth);
  const days = useMemo(
    () => calendarDays(month, weekStartsOn),
    [month.getFullYear(), month.getMonth(), weekStartsOn],
  );
  const weekdayLabels = weekStartsOn === 1 ? MONDAY_LABELS : SUNDAY_LABELS;
  const minimum = minDate ? startOfDay(minDate) : null;
  const maximum = maxDate ? startOfDay(maxDate) : null;
  const wheelOpen = monthYearDropdown && pickerOpen;

  useEffect(() => {
    Animated.timing(chevron, {
      toValue: pickerOpen ? 1 : 0,
      duration: t.motion.duration.instant,
      useNativeDriver: true,
    }).start();
  }, [chevron, pickerOpen, t.motion.duration.instant]);

  function changeMonth(amount: number) {
    if (disabled) return;
    const next = addMonths(month, amount);
    if (displayedMonth === undefined) setInternalMonth(next);
    onDisplayedMonthChange?.(next);
  }

  function selectDate(date: Date) {
    if (disabled) return;
    if (value === undefined) setInternalValue(date);
    if (displayedMonth === undefined && date.getMonth() !== month.getMonth()) {
      setInternalMonth(startOfMonth(date));
    }
    onValueChange?.(date);
  }

  function setMonthFromWheel(next: Date) {
    if (disabled) return;
    const nextMonth = startOfMonth(next);
    if (displayedMonth === undefined) setInternalMonth(nextMonth);
    onDisplayedMonthChange?.(nextMonth);
  }

  return (
    <View
      accessibilityLabel="Date picker"
      style={[
        {
          width: '100%',
          maxWidth: 350,
          padding: t.spacing[3],
          borderRadius: t.radii.xl,
          borderWidth: 1,
          borderColor: t.colors.borderSecondary,
          backgroundColor: t.colors.surfaceElevated,
          opacity: disabled ? 0.48 : 1,
        },
        style,
      ]}
      {...rest}
    >
      <View
        style={{
          minHeight: t.sizing.touchTarget.minimum,
          flexDirection: 'row',
          alignItems: 'center',
          justifyContent: 'space-between',
          marginBottom: t.spacing[2],
        }}
      >
        {monthYearDropdown ? (
          <Pressable
            accessibilityRole="button"
            accessibilityLabel={`${monthLabel(month, locale)}, choose month and year`}
            accessibilityState={{ expanded: pickerOpen, disabled }}
            disabled={disabled}
            hitSlop={6}
            onPress={() => setPickerOpen((open) => !open)}
            style={{ flexDirection: 'row', alignItems: 'center', gap: t.spacing[1] }}
          >
            <Text
              style={{
                color: t.colors.textPrimary,
                fontFamily: t.fontFamilies.sans,
                ...t.typography.headingMediumEmphasized,
              }}
            >
              {monthLabel(month, locale)}
            </Text>
            <Animated.View
              style={{
                marginTop: -2,
                transform: [
                  { rotate: chevron.interpolate({ inputRange: [0, 1], outputRange: ['0deg', '180deg'] }) },
                ],
              }}
            >
              <View
                style={{
                  width: 7,
                  height: 7,
                  borderRightWidth: 2,
                  borderBottomWidth: 2,
                  borderColor: t.colors.textPrimary,
                  transform: [{ rotate: '45deg' }],
                }}
              />
            </Animated.View>
          </Pressable>
        ) : (
          <Text
            accessibilityRole="header"
            style={{
              color: t.colors.textPrimary,
              fontFamily: t.fontFamilies.sans,
              ...t.typography.headingMediumEmphasized,
            }}
          >
            {monthLabel(month, locale)}
          </Text>
        )}
        {!wheelOpen ? (
          <View style={{ flexDirection: 'row', gap: t.spacing[1] }}>
            <MonthButton
              label="Previous month"
              glyph="‹"
              disabled={disabled || Boolean(minimum && addMonths(month, -1) < startOfMonth(minimum))}
              onPress={() => changeMonth(-1)}
            />
            <MonthButton
              label="Next month"
              glyph="›"
              disabled={disabled || Boolean(maximum && addMonths(month, 1) > startOfMonth(maximum))}
              onPress={() => changeMonth(1)}
            />
          </View>
        ) : null}
      </View>

      {wheelOpen ? (
        <DateWheelPicker
          mode="month-year"
          value={month}
          onValueChange={setMonthFromWheel}
          minDate={minDate}
          maxDate={maxDate}
          locale={locale}
          disabled={disabled}
          style={{ borderWidth: 0, backgroundColor: 'transparent', width: '100%' }}
        />
      ) : (
        <>
      <View style={{ flexDirection: 'row' }}>
        {weekdayLabels.map((label, index) => (
          <View key={`${label}-${index}`} style={{ width: `${100 / 7}%`, alignItems: 'center' }}>
            <Text
              style={{
                color: t.colors.textTertiary,
                fontFamily: t.fontFamilies.sans,
                ...t.typography.labelSmall,
                fontWeight: t.fontWeights.semibold,
              }}
            >
              {label}
            </Text>
          </View>
        ))}
      </View>

      <View style={{ flexDirection: 'row', flexWrap: 'wrap', marginTop: t.spacing[1] }}>
        {days.map((date) => {
          const outside = date.getMonth() !== month.getMonth();
          const chosen = sameDay(date, selected);
          const current = sameDay(date, today);
          const unavailable = Boolean(
            disabled ||
              (minimum && date < minimum) ||
              (maximum && date > maximum) ||
              isDateDisabled?.(date),
          );
          const hidden = outside && !showOutsideDays;

          return (
            <View
              key={`${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`}
              style={{
                width: `${100 / 7}%`,
                height: t.sizing.touchTarget.minimum,
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              {!hidden ? (
                <Pressable
                  accessibilityRole="button"
                  accessibilityLabel={accessibilityDateLabel(date, locale)}
                  accessibilityHint={outside ? 'Selects this date and opens its month' : undefined}
                  accessibilityState={{ selected: chosen, disabled: unavailable }}
                  disabled={unavailable}
                  hitSlop={2}
                  onPress={() => selectDate(date)}
                  style={({ pressed }) => ({
                    width: 36,
                    height: 36,
                    alignItems: 'center',
                    justifyContent: 'center',
                    borderRadius: 18,
                    borderWidth: current && !chosen ? 1 : 0,
                    borderColor: t.colors.borderFocus,
                    backgroundColor: chosen
                      ? t.colors.interactivePrimary
                      : pressed
                        ? t.colors.interactiveSecondaryPressed
                        : 'transparent',
                  })}
                >
                  <Text
                    style={{
                      color: chosen
                        ? t.colors.textInteractivePrimary
                        : unavailable
                          ? t.colors.textTertiary
                          : outside
                            ? t.colors.textTertiary
                            : t.colors.textPrimary,
                      fontFamily: t.fontFamilies.sans,
                      ...t.typography.bodyMedium,
                      fontWeight: chosen ? t.fontWeights.semibold : t.fontWeights.medium,
                      opacity: unavailable ? 0.46 : 1,
                    }}
                  >
                    {date.getDate()}
                  </Text>
                </Pressable>
              ) : null}
            </View>
          );
        })}
      </View>
        </>
      )}
    </View>
  );
}

function MonthButton({
  label,
  glyph,
  disabled,
  onPress,
}: {
  label: string;
  glyph: string;
  disabled: boolean;
  onPress: () => void;
}) {
  const t = useTokens();

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={label}
      accessibilityState={{ disabled }}
      disabled={disabled}
      onPress={onPress}
      hitSlop={4}
      style={({ pressed }) => ({
        width: t.sizing.buttonHeight.md,
        height: t.sizing.buttonHeight.md,
        alignItems: 'center',
        justifyContent: 'center',
        borderRadius: t.radii.full,
        backgroundColor: pressed ? t.colors.interactiveSecondaryPressed : 'transparent',
        opacity: disabled ? 0.32 : 1,
      })}
    >
      <Text
        style={{
          marginTop: -3,
          color: t.colors.textSecondary,
          fontFamily: t.fontFamilies.sans,
          ...t.typography.displayMedium,
        }}
      >
        {glyph}
      </Text>
    </Pressable>
  );
}

import { useEffect, useMemo, useRef, useState } from 'react';
import {
  FlatList,
  Pressable,
  Text,
  View,
  type NativeScrollEvent,
  type NativeSyntheticEvent,
  type StyleProp,
  type ViewProps,
  type ViewStyle,
} from 'react-native';
import { useTokens } from '../../foundation/theme-provider';

export type DateWheelPickerMode = 'date' | 'time' | 'date-time' | 'month-year';
export type DateWheelPickerHourCycle = 12 | 24;
export type DateWheelPickerMinuteInterval = 1 | 5 | 10 | 15 | 30;

export type DateWheelPickerProps = Omit<ViewProps, 'style'> & {
  value?: Date;
  defaultValue?: Date;
  onValueChange?: (date: Date) => void;
  mode?: DateWheelPickerMode;
  minDate?: Date;
  maxDate?: Date;
  locale?: string;
  hourCycle?: DateWheelPickerHourCycle;
  minuteInterval?: DateWheelPickerMinuteInterval;
  dateRangeDays?: number;
  disabled?: boolean;
  style?: StyleProp<ViewStyle>;
};

type WheelValue = string | number;
type WheelItem = {
  value: WheelValue;
  label: string;
  accessibilityLabel?: string;
};

const ITEM_HEIGHT = 44;
const VISIBLE_ITEMS = 5;
const WHEEL_HEIGHT = ITEM_HEIGHT * VISIBLE_ITEMS;
const WHEEL_PADDING = ITEM_HEIGHT * Math.floor(VISIBLE_ITEMS / 2);

function startOfDay(date: Date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function addDays(date: Date, amount: number) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + amount);
}

function daysInMonth(year: number, month: number) {
  return new Date(year, month + 1, 0).getDate();
}

function sameDay(a: Date, b: Date) {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

function clampDate(date: Date, minDate?: Date, maxDate?: Date) {
  const time = Math.min(
    maxDate?.getTime() ?? Number.POSITIVE_INFINITY,
    Math.max(minDate?.getTime() ?? Number.NEGATIVE_INFINITY, date.getTime()),
  );
  return new Date(time);
}

function withDateParts(date: Date, parts: { year?: number; month?: number; day?: number }) {
  const year = parts.year ?? date.getFullYear();
  const month = parts.month ?? date.getMonth();
  const day = Math.min(parts.day ?? date.getDate(), daysInMonth(year, month));
  return new Date(year, month, day, date.getHours(), date.getMinutes(), date.getSeconds());
}

function formatDateItem(date: Date, locale?: string) {
  const today = startOfDay(new Date());
  if (sameDay(date, today)) return 'Today';
  if (sameDay(date, addDays(today, -1))) return 'Yesterday';
  if (sameDay(date, addDays(today, 1))) return 'Tomorrow';

  try {
    return new Intl.DateTimeFormat(locale, {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
    }).format(date);
  } catch {
    return date.toDateString().slice(0, 10);
  }
}

function formatFullDate(date: Date, locale?: string) {
  try {
    return new Intl.DateTimeFormat(locale, { dateStyle: 'full' }).format(date);
  } catch {
    return date.toDateString();
  }
}

function monthItems(locale?: string): WheelItem[] {
  return Array.from({ length: 12 }, (_, month) => {
    let label: string;
    try {
      label = new Intl.DateTimeFormat(locale, { month: 'long' }).format(new Date(2024, month, 1));
    } catch {
      label = new Date(2024, month, 1).toLocaleString('en', { month: 'long' });
    }
    return { value: month, label };
  });
}

export function DateWheelPicker({
  value,
  defaultValue,
  onValueChange,
  mode = 'date-time',
  minDate,
  maxDate,
  locale,
  hourCycle = 12,
  minuteInterval = 5,
  dateRangeDays = 365,
  disabled = false,
  style,
  ...rest
}: DateWheelPickerProps) {
  const t = useTokens();
  const [fallbackValue] = useState(() => defaultValue ?? new Date());
  const [initialYear] = useState(() =>
    clampDate(value ?? fallbackValue, minDate, maxDate).getFullYear(),
  );
  const [anchorTime] = useState(() =>
    startOfDay(clampDate(value ?? fallbackValue, minDate, maxDate)).getTime(),
  );
  const [internalValue, setInternalValue] = useState(() =>
    clampDate(fallbackValue, minDate, maxDate),
  );
  const selected = clampDate(value ?? internalValue, minDate, maxDate);
  const selectedYear = selected.getFullYear();
  const selectedMonth = selected.getMonth();
  const minTime = minDate?.getTime();
  const maxTime = maxDate?.getTime();

  function changeValue(next: Date) {
    if (disabled) return;
    const clamped = clampDate(next, minDate, maxDate);
    if (value === undefined) setInternalValue(clamped);
    onValueChange?.(clamped);
  }

  const months = useMemo(() => monthItems(locale), [locale]);
  // Keep the range stable while the wheel settles. Re-centering it around every
  // selected year changes the value represented by each visible row mid-scroll.
  const yearFloor = minDate?.getFullYear() ?? initialYear - 100;
  const yearCeiling = maxDate?.getFullYear() ?? initialYear + 100;
  const years = useMemo(
    () =>
      Array.from({ length: Math.max(1, yearCeiling - yearFloor + 1) }, (_, index) => ({
        value: yearFloor + index,
        label: String(yearFloor + index),
      })),
    [yearCeiling, yearFloor],
  );
  const days = useMemo(
    () =>
      Array.from({ length: daysInMonth(selectedYear, selectedMonth) }, (_, index) => ({
        value: index + 1,
        label: String(index + 1).padStart(2, '0'),
      })),
    [selectedMonth, selectedYear],
  );

  // Anchor the rolling range on a stable initial date (like the year range).
  // Re-centering it on `selectedTime` shifts the value under each visible row
  // mid-scroll, so a picked date lands on a different one after the list rebuilds.
  const rollingDates = useMemo(() => {
    const range = Math.max(1, Math.floor(dateRangeDays));
    const anchorDate = new Date(anchorTime);
    const first = startOfDay(minTime == null ? addDays(anchorDate, -range) : new Date(minTime));
    const last = startOfDay(maxTime == null ? addDays(anchorDate, range) : new Date(maxTime));
    const length = Math.max(1, Math.floor((last.getTime() - first.getTime()) / 86_400_000) + 1);
    return Array.from({ length }, (_, index) => {
      const date = addDays(first, index);
      return {
        value: date.getTime(),
        label: formatDateItem(date, locale),
        accessibilityLabel: formatFullDate(date, locale),
      };
    });
  }, [anchorTime, dateRangeDays, locale, maxTime, minTime]);

  const hourItems = useMemo(
    () =>
      Array.from({ length: hourCycle === 12 ? 12 : 24 }, (_, index) => {
        const hour = hourCycle === 12 ? index + 1 : index;
        return { value: hour, label: String(hour).padStart(2, '0') };
      }),
    [hourCycle],
  );
  const minuteItems = useMemo(
    () =>
      Array.from({ length: Math.ceil(60 / minuteInterval) }, (_, index) => {
        const minute = index * minuteInterval;
        return { value: minute, label: String(minute).padStart(2, '0') };
      }),
    [minuteInterval],
  );
  const periodItems: WheelItem[] = [
    { value: 'AM', label: 'AM' },
    { value: 'PM', label: 'PM' },
  ];

  const selectedHour =
    hourCycle === 12 ? ((selected.getHours() + 11) % 12) + 1 : selected.getHours();
  const selectedMinute = Math.floor(selected.getMinutes() / minuteInterval) * minuteInterval;
  const selectedPeriod = selected.getHours() >= 12 ? 'PM' : 'AM';

  function setHour(hour: number) {
    let nextHour = hour;
    if (hourCycle === 12) {
      nextHour = hour % 12;
      if (selectedPeriod === 'PM') nextHour += 12;
    }
    const next = new Date(selected);
    next.setHours(nextHour);
    changeValue(next);
  }

  function setPeriod(period: WheelValue) {
    const next = new Date(selected);
    const hour = selected.getHours();
    next.setHours(period === 'PM' ? (hour % 12) + 12 : hour % 12);
    changeValue(next);
  }

  function setMinute(minute: number) {
    const next = new Date(selected);
    next.setMinutes(minute);
    changeValue(next);
  }

  const showDateColumns = mode === 'date' || mode === 'month-year';
  const showRollingDate = mode === 'date-time';
  const showTime = mode === 'time' || mode === 'date-time';

  return (
    <View
      accessibilityLabel="Date wheel picker"
      style={[
        {
          width: '100%',
          maxWidth: 350,
          height: WHEEL_HEIGHT,
          borderRadius: t.radii.xl,
          borderWidth: 1,
          borderColor: t.colors.borderSecondary,
          backgroundColor: t.colors.surfaceElevated,
          overflow: 'hidden',
          opacity: disabled ? 0.48 : 1,
        },
        style,
      ]}
      {...rest}
    >
      <View
        pointerEvents="none"
        style={{
          position: 'absolute',
          top: WHEEL_PADDING,
          left: t.spacing[2],
          right: t.spacing[2],
          height: ITEM_HEIGHT,
          borderRadius: t.radii.lg,
          backgroundColor: t.colors.surfaceInput,
        }}
      />

      <View style={{ flex: 1, flexDirection: 'row', paddingHorizontal: t.spacing[2] }}>
        {showRollingDate ? (
          <WheelColumn
            accessibilityLabel="Date"
            items={rollingDates}
            selectedValue={startOfDay(selected).getTime()}
            onValueChange={(next) => {
              const date = new Date(Number(next));
              date.setHours(selected.getHours(), selected.getMinutes(), selected.getSeconds());
              changeValue(date);
            }}
            disabled={disabled}
            flex={2.25}
          />
        ) : null}

        {showDateColumns ? (
          <>
            <WheelColumn
              accessibilityLabel="Month"
              items={months}
              selectedValue={selected.getMonth()}
              onValueChange={(month) =>
                changeValue(withDateParts(selected, { month: Number(month) }))
              }
              disabled={disabled}
              flex={1.7}
            />
            {mode === 'date' ? (
              <WheelColumn
                accessibilityLabel="Day"
                items={days}
                selectedValue={selected.getDate()}
                onValueChange={(day) => changeValue(withDateParts(selected, { day: Number(day) }))}
                disabled={disabled}
              />
            ) : null}
            <WheelColumn
              accessibilityLabel="Year"
              items={years}
              selectedValue={selected.getFullYear()}
              onValueChange={(year) => changeValue(withDateParts(selected, { year: Number(year) }))}
              disabled={disabled}
              flex={1.25}
            />
          </>
        ) : null}

        {showTime ? (
          <>
            <WheelColumn
              accessibilityLabel="Hour"
              items={hourItems}
              selectedValue={selectedHour}
              onValueChange={(hour) => setHour(Number(hour))}
              disabled={disabled}
            />
            <WheelColumn
              accessibilityLabel="Minute"
              items={minuteItems}
              selectedValue={selectedMinute}
              onValueChange={(minute) => setMinute(Number(minute))}
              disabled={disabled}
            />
            {hourCycle === 12 ? (
              <WheelColumn
                accessibilityLabel="Period"
                items={periodItems}
                selectedValue={selectedPeriod}
                onValueChange={setPeriod}
                disabled={disabled}
              />
            ) : null}
          </>
        ) : null}
      </View>

      <View
        pointerEvents="none"
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          height: ITEM_HEIGHT,
          backgroundColor: t.colors.surfaceElevated,
          opacity: 0.72,
        }}
      />
      <View
        pointerEvents="none"
        style={{
          position: 'absolute',
          bottom: 0,
          left: 0,
          right: 0,
          height: ITEM_HEIGHT,
          backgroundColor: t.colors.surfaceElevated,
          opacity: 0.72,
        }}
      />
    </View>
  );
}

function WheelColumn({
  accessibilityLabel,
  items,
  selectedValue,
  onValueChange,
  disabled,
  flex = 1,
}: {
  accessibilityLabel: string;
  items: WheelItem[];
  selectedValue: WheelValue;
  onValueChange: (value: WheelValue) => void;
  disabled: boolean;
  flex?: number;
}) {
  const t = useTokens();
  const listRef = useRef<FlatList<WheelItem>>(null);
  const selectedIndex = Math.max(
    0,
    items.findIndex((item) => item.value === selectedValue),
  );

  useEffect(() => {
    listRef.current?.scrollToOffset({ offset: selectedIndex * ITEM_HEIGHT, animated: false });
  }, [items.length, selectedIndex]);

  function selectIndex(index: number) {
    const nextIndex = Math.max(0, Math.min(items.length - 1, index));
    const item = items[nextIndex];
    if (item && item.value !== selectedValue) onValueChange(item.value);
  }

  function settle(event: NativeSyntheticEvent<NativeScrollEvent>) {
    selectIndex(Math.round(event.nativeEvent.contentOffset.y / ITEM_HEIGHT));
  }

  return (
    <View
      accessibilityRole="adjustable"
      accessibilityLabel={accessibilityLabel}
      accessibilityValue={{
        text: items[selectedIndex]?.accessibilityLabel ?? items[selectedIndex]?.label,
      }}
      accessibilityActions={[
        { name: 'increment', label: `Next ${accessibilityLabel.toLowerCase()}` },
        { name: 'decrement', label: `Previous ${accessibilityLabel.toLowerCase()}` },
      ]}
      onAccessibilityAction={(event) => {
        const amount = event.nativeEvent.actionName === 'increment' ? 1 : -1;
        const nextIndex = Math.max(0, Math.min(items.length - 1, selectedIndex + amount));
        listRef.current?.scrollToOffset({ offset: nextIndex * ITEM_HEIGHT, animated: true });
        selectIndex(nextIndex);
      }}
      style={{ flex }}
    >
      <FlatList
        ref={listRef}
        testID={`${accessibilityLabel.toLowerCase()}-wheel`}
        data={items}
        keyExtractor={(item) => String(item.value)}
        getItemLayout={(_, index) => ({
          length: ITEM_HEIGHT,
          offset: ITEM_HEIGHT * index,
          index,
        })}
        initialScrollIndex={selectedIndex}
        contentContainerStyle={{ paddingVertical: WHEEL_PADDING }}
        showsVerticalScrollIndicator={false}
        scrollEnabled={!disabled}
        snapToInterval={ITEM_HEIGHT}
        snapToAlignment="start"
        decelerationRate="fast"
        onMomentumScrollEnd={settle}
        onScrollEndDrag={(event) => {
          if (Math.abs(event.nativeEvent.velocity?.y ?? 0) < 0.1) settle(event);
        }}
        renderItem={({ item, index }) => {
          const distance = Math.abs(index - selectedIndex);
          return (
            <Pressable
              disabled={disabled}
              onPress={() => {
                listRef.current?.scrollToOffset({ offset: index * ITEM_HEIGHT, animated: true });
                selectIndex(index);
              }}
              style={{
                height: ITEM_HEIGHT,
                alignItems: 'center',
                justifyContent: 'center',
                paddingHorizontal: t.spacing[1],
              }}
            >
              <Text
                numberOfLines={1}
                adjustsFontSizeToFit
                minimumFontScale={0.72}
                style={{
                  color: distance === 0 ? t.colors.textPrimary : t.colors.textTertiary,
                  fontFamily: t.fontFamilies.sans,
                  ...(distance === 0
                    ? t.typography.headingMediumEmphasized
                    : t.typography.bodyMedium),
                  fontWeight: distance === 0 ? t.fontWeights.semibold : t.fontWeights.medium,
                  opacity: distance === 0 ? 1 : distance === 1 ? 0.62 : 0.3,
                }}
              >
                {item.label}
              </Text>
            </Pressable>
          );
        }}
      />
    </View>
  );
}

